import { spawn } from 'node:child_process';
import type { Writable } from 'node:stream';

/**
 * FFmpeg integration. Arguments are always built as an array from validated,
 * typed values and passed to spawn() without a shell. Nothing from user input
 * is ever interpolated into a filtergraph or command string.
 */

export type Quality = 'draft' | 'standard' | 'high';

export interface EncodeOptions {
  width: number;
  height: number;
  fps: number;
  /** Local path of the source audio. Must be generated by the worker, not by the user. */
  audioPath: string;
  /** Local output path. Must be generated by the worker, not by the user. */
  outputPath: string;
  quality?: Quality;
  /** Encoder thread limit; 0 lets the encoder decide. */
  threads?: number;
}

const QUALITY: Record<Quality, { preset: string; crf: number; audioBitrate: string }> = {
  draft: { preset: 'ultrafast', crf: 28, audioBitrate: '128k' },
  standard: { preset: 'veryfast', crf: 20, audioBitrate: '192k' },
  high: { preset: 'medium', crf: 17, audioBitrate: '256k' },
};

const MAX_DIMENSION = 3840;
const MAX_FPS = 60;
/** Only local files and pipes: a crafted input must not make FFmpeg open URLs. */
const PROTOCOL_WHITELIST = 'file,pipe';

function assertIntInRange(name: string, value: number, min: number, max: number): void {
  if (!Number.isInteger(value) || value < min || value > max) {
    throw new RangeError(`${name} must be an integer in [${min}, ${max}], got ${value}`);
  }
}

function assertLocalPath(name: string, value: string): void {
  if (typeof value !== 'string' || value.length === 0 || value.includes('\0')) {
    throw new TypeError(`${name} must be a non-empty path`);
  }
  // A leading '-' would be parsed as an option; a scheme would be parsed as a protocol.
  if (value.startsWith('-') || /^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(value)) {
    throw new TypeError(`${name} must be a plain local file path, got ${JSON.stringify(value)}`);
  }
}

/** Builds arguments for encoding raw RGBA frames from stdin plus an audio file into MP4. */
export function buildEncodeArgs(options: EncodeOptions): string[] {
  const { width, height, fps, audioPath, outputPath, quality = 'standard', threads = 0 } = options;
  assertIntInRange('width', width, 16, MAX_DIMENSION);
  assertIntInRange('height', height, 16, MAX_DIMENSION);
  if (width % 2 !== 0 || height % 2 !== 0) {
    throw new RangeError('width and height must be even for yuv420p output');
  }
  assertIntInRange('fps', fps, 1, MAX_FPS);
  assertIntInRange('threads', threads, 0, 64);
  assertLocalPath('audioPath', audioPath);
  assertLocalPath('outputPath', outputPath);
  const settings = QUALITY[quality];
  if (!settings) throw new RangeError(`Unknown quality: ${String(quality)}`);

  return [
    '-hide_banner', '-loglevel', 'error', '-nostdin', '-y',
    '-f', 'rawvideo', '-pix_fmt', 'rgba', '-s', `${width}x${height}`, '-r', String(fps),
    '-i', 'pipe:0',
    '-protocol_whitelist', PROTOCOL_WHITELIST, '-i', audioPath,
    '-map', '0:v:0', '-map', '1:a:0',
    '-c:v', 'libx264', '-preset', settings.preset, '-crf', String(settings.crf),
    '-pix_fmt', 'yuv420p', '-threads', String(threads),
    '-c:a', 'aac', '-b:a', settings.audioBitrate,
    '-shortest', '-movflags', '+faststart',
    '-f', 'mp4', outputPath,
  ];
}

/** Builds arguments for decoding any supported audio file to mono 32-bit float PCM on stdout. */
export function buildDecodeArgs(audioPath: string, sampleRate: number): string[] {
  assertLocalPath('audioPath', audioPath);
  assertIntInRange('sampleRate', sampleRate, 8000, 96000);
  return [
    '-hide_banner', '-loglevel', 'error', '-nostdin',
    '-protocol_whitelist', PROTOCOL_WHITELIST, '-i', audioPath,
    '-map', '0:a:0', '-vn', '-ac', '1', '-ar', String(sampleRate),
    '-f', 'f32le', 'pipe:1',
  ];
}

export interface ProcessOptions {
  ffmpegPath?: string;
  signal?: AbortSignal;
}

export interface Encoder {
  /** Writes one RGBA frame, waiting when FFmpeg applies backpressure. */
  writeFrame(frame: Uint8Array): Promise<void>;
  /** Closes the input and resolves once FFmpeg has finished writing the file. */
  finish(): Promise<void>;
}

export function startEncoder(options: EncodeOptions, process: ProcessOptions = {}): Encoder {
  const frameBytes = options.width * options.height * 4;
  const child = spawn(process.ffmpegPath ?? 'ffmpeg', buildEncodeArgs(options), {
    stdio: ['pipe', 'ignore', 'pipe'],
    signal: process.signal,
  });
  const stdin: Writable = child.stdin;
  let stderr = '';
  child.stderr.on('data', (chunk: Buffer) => {
    if (stderr.length < 8192) stderr += chunk.toString();
  });

  let failure: Error | undefined;
  const exited = new Promise<void>((resolve, reject) => {
    child.on('error', (error) => {
      failure = error;
      reject(error);
    });
    child.on('close', (code) => {
      if (code === 0) return resolve();
      failure = new Error(`ffmpeg exited with code ${code}: ${stderr.trim()}`);
      reject(failure);
    });
  });
  // Surface the failure through writeFrame/finish instead of an unhandled rejection.
  exited.catch(() => {});
  stdin.on('error', (error) => {
    failure ??= error;
  });

  return {
    async writeFrame(frame) {
      if (failure) throw failure;
      if (frame.byteLength !== frameBytes) {
        throw new RangeError(`Frame must be ${frameBytes} bytes, got ${frame.byteLength}`);
      }
      if (!stdin.write(frame)) {
        await new Promise<void>((resolve) => {
          const done = () => {
            stdin.off('drain', done);
            child.off('close', done);
            resolve();
          };
          stdin.once('drain', done);
          child.once('close', done);
        });
      }
    },
    async finish() {
      stdin.end();
      await exited;
    },
  };
}

/** Decodes an audio file to mono PCM in memory. Intended for tracks within the upload limits. */
export function decodeAudio(
  audioPath: string,
  sampleRate: number,
  process: ProcessOptions = {},
): Promise<Float32Array> {
  return new Promise((resolve, reject) => {
    const child = spawn(process.ffmpegPath ?? 'ffmpeg', buildDecodeArgs(audioPath, sampleRate), {
      stdio: ['ignore', 'pipe', 'pipe'],
      signal: process.signal,
    });
    const chunks: Buffer[] = [];
    let stderr = '';
    child.stdout.on('data', (chunk: Buffer) => chunks.push(chunk));
    child.stderr.on('data', (chunk: Buffer) => {
      if (stderr.length < 8192) stderr += chunk.toString();
    });
    child.on('error', reject);
    child.on('close', (code) => {
      if (code !== 0) {
        return reject(new Error(`ffmpeg exited with code ${code}: ${stderr.trim()}`));
      }
      const bytes = Buffer.concat(chunks);
      const usable = bytes.byteLength - (bytes.byteLength % 4);
      // Copy into an aligned buffer; Buffer.concat does not guarantee 4-byte alignment.
      const aligned = new Uint8Array(usable);
      aligned.set(bytes.subarray(0, usable));
      resolve(new Float32Array(aligned.buffer));
    });
  });
}
